def min_cost(cost, m, n):
    # Base case
    if m == 0 and n == 0:
        return 0
    # Recursive case
    if m == 0:
        return cost[0][n]
    if n == 0:
        return cost[m][0]
    # Find the minimum cost of going up, down, left, or right
    return min(cost[m][n] + min_cost(cost, m - 1, n),
               cost[m][n] + min_cost(cost, m, n - 1),
               cost[m][n] + min_cost(cost, m - 1, n - 1),
               cost[m][n] + min_cost(cost, m, n + 1))

